options.customCss:
:root {
  /* Oracle Inspired Colors */
  --chat--color-primary: #f80000;
  --chat--color-primary-shade-50: #e60000;
  --chat--color-primary-shade-100: #cc0000;

  --chat--color-secondary: #1f2937;
  --chat--color-secondary-shade-50: #374151;

  --chat--color-white: #ffffff;
  --chat--color-light: #f7f7f8;
  --chat--color-light-shade-50: #ececec;
  --chat--color-light-shade-100: #d1d5db;

  --chat--color-medium: #9ca3af;
  --chat--color-dark: #111111;
  --chat--color-disabled: #d1d5db;
  --chat--color-typing: #6b7280;

  /* Layout */
  --chat--spacing: 1rem;
  --chat--border-radius: 10px;
  --chat--transition-duration: 0.15s;

  --chat--font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Inter, Helvetica, Arial, sans-serif;

  /* Window */
  --chat--window--width: 420px;
  --chat--window--height: 640px;
  --chat--window--bottom: var(--chat--spacing);
  --chat--window--right: var(--chat--spacing);
  --chat--window--z-index: 9999;
  --chat--window--border: 1px solid var(--chat--color-light-shade-50);
  --chat--window--border-radius: 14px;
  --chat--window--margin-bottom: var(--chat--spacing);

  /* Header */
  --chat--header--padding: 1rem 1.2rem;
  --chat--header--background: var(--chat--color-white);
  --chat--header--color: var(--chat--color-dark);
  --chat--header--border-bottom: 1px solid var(--chat--color-light-shade-50);

  --chat--heading--font-size: 1.1rem;
  --chat--subtitle--font-size: 0.85rem;

  /* Messages */

  --chat--message--font-size: 0.95rem;
  --chat--message--padding: 0.7rem 0.9rem;
  --chat--message--border-radius: 12px;
  --chat--message-line-height: 1.5;
  --chat--message--margin-bottom: 0.7rem;

  /* Bot */

  --chat--message--bot--background: #ffffff;
  --chat--message--bot--color: #111111;
  --chat--message--bot--border: 1px solid #eeeeee;

  /* User */

  --chat--message--user--background: #f80000;
  --chat--message--user--color: #ffffff;
  --chat--message--user--border: none;

  --chat--messages-list--padding: 1rem;

  /* Toggle Button */

  --chat--toggle--size: 58px;
  --chat--toggle--border-radius: 50%;
  --chat--toggle--background: #f80000;
  --chat--toggle--hover--background: #e60000;
  --chat--toggle--active--background: #cc0000;
  --chat--toggle--color: #ffffff;

  /* Input */

  --chat--textarea--height: 52px;
  --chat--textarea--max-height: 30rem;

  --chat--input--font-size: 0.95rem;
  --chat--input--border: none;
  --chat--input--border-radius: 10px;
  --chat--input--padding: 0.8rem 1rem;

  --chat--input--background: #ffffff;
  --chat--input--text-color: #111111;

  --chat--input--placeholder--font-size: 0.9rem;

  /* Buttons */

  --chat--button--color: #ffffff;
  --chat--button--background: #f80000;
  --chat--button--border-radius: 8px;

  --chat--button--hover--background: #e60000;

  /* Send button */

  --chat--input--send--button--background: transparent;
  --chat--input--send--button--color: #f80000;
  --chat--input--send--button--background-hover: #fff5f5;
  --chat--input--send--button--color-hover: #e60000;

  /* File button */

  --chat--input--file--button--background: transparent;
  --chat--input--file--button--color: #6b7280;

  /* Body */

  --chat--body--background: #f7f7f8;
  --chat--footer--background: #ffffff;
  --chat--footer--color: #111111;
}

/* Message width similar to modern chat UIs */

.chat-message {
  max-width: 65%;
}

/* Slight card effect */

.chat-window {
  box-shadow: 0 8px 30px rgba(0,0,0,0.08);
}

/* Smooth modern message appearance */

.chat-message {
  animation: fadeIn 0.2s ease;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
